```typescript
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Proper mocks. None of this silly guessing business.
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Sensible Hat', price: 29.99 },
  { id: '2', name: 'Walking Stick', price: 45.00 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 74.99,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // HAPPY PATH - The proper way through
  describe('Complete Checkout Flow', () => {
    it('navigates through all steps and confirms order', async () => {
      render(<Checkout onComplete={mockOnComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Sensible Lane');
      await user.type(screen.getByLabelText(/city/i), 'London');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'John Cleese');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/sensible hat/i)).toBeInTheDocument();
      expect(screen.getByText(/\$74\.99/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await screen.findByRole('status');
      expect(screen.getByText(/ORD-12345/)).toBeInTheDocument();
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // VALIDATION - No silliness permitted
  describe('Form Validation', () => {
    it('displays shipping errors for empty fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'silly');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      // Navigate to payment first
      await user.type(screen.getByLabelText(/street/i), '123 Test');
      await user.type(screen.getByLabelText(/city/i), 'City');
      await user.selectOptions(screen.getByLabelText(/state/i), 'NY');
      await user.type(screen.getByLabelText(/zip/i), '10001');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      await user.type(screen.getByLabelText(/card number/i), '1234');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      expect(screen.getByText(/valid 16-digit card number/i)).toBeInTheDocument();
    });
  });

  // ERROR STATES
  describe('Error Handling', () => {
    it('displays payment failure and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);

      // Quick navigation to review
      // ... (fill forms, abbreviated for space)

      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);

      // Retry succeeds
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-99999' });
      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByText(/ORD-99999/)).toBeInTheDocument();
    });
  });

  // LOADING STATES
  describe('Loading States', () => {
    it('disables buttons during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      render(<Checkout />);
      // Navigate to review...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  // ACCESSIBILITY - No exceptions
  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('uses proper ARIA attributes for progress', () => {
      render(<Checkout />);
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      expect(within(nav).getByText('Shipping')).toHaveAttribute('aria-current', 'step');
    });
  });

  // EDGE CASES
  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});
```

